import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.gku7e_5h.js";const f=JSON.parse('{"title":"About","description":"","frontmatter":{"title":"About"},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1749216009000}'),n={name:"about.md"};function i(s,e,l,h,d,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h2 id="who-am-i" tabindex="-1">Who am I? <a class="header-anchor" href="#who-am-i" aria-label="Permalink to &quot;Who am I?&quot;">​</a></h2><p>I&#39;ve gone from teaching art and technology courses on Nantucket to training school administrators and teachers in Arusha, Tanzania. Along the way, I have collaborated with a wide array of professionals and learners, honed my coding chops, and become fluent in Swahili. My students in Tanzania won <a href="https://www.youngscientists.co.tz/fileadmin/user_upload/user_upload_A/Posters_2015/St_Jude.pdf" target="_blank" rel="noreferrer">first prize in technology</a> at a national science competition for their Raspberry Pi powered, SMS enabled model smart home. Since returning home to Cape Cod I have worked on the field crew of <a href="https://www.archatchery.com/" target="_blank" rel="noreferrer">Aquacultural Research Corporation</a>, managed technology projects for a public school district. As the systems manager of <a href="https://info.clamsnet.org" target="_blank" rel="noreferrer">CLAMS</a> I helped migrate data to Koha and implement integration projects.</p><p>I like playing with synthesizers, drum machines and skateboards. 🎹 🎛️ 🛹</p><h2 id="what-are-chrono-synclastic-infundibula" tabindex="-1">What are chrono-synclastic infundibula? <a class="header-anchor" href="#what-are-chrono-synclastic-infundibula" aria-label="Permalink to &quot;What are chrono-synclastic infundibula?&quot;">​</a></h2><p>⏳ <strong>Chrono</strong> from Greek, χρόνος (khrónos, “time”), meaning time</p><p>🌐 <strong>Synclastic</strong> from Greek, σύν (sún, “with, together”) + κλαστός (klastós, “broken in pieces”) + -ic, meaning curved towards the same side in all directions</p><p>🌪️ <strong>Infundibulum</strong> from Latin, meaning funnel</p><p>This phenomenon from the 1959 novel <a href="https://en.wikipedia.org/wiki/The_Sirens_of_Titan" target="_blank" rel="noreferrer">The Sirens of Titan</a> by <a href="https://en.wikipedia.org/wiki/Kurt_Vonnegut" target="_blank" rel="noreferrer">Kurt Vonnegut</a> is something like a black hole or time warp. 🕳️</p><p>When you enter a chrono-synclastic infundibulum, you are multiplied across time and space. Your normal human conciousness is altered, enabling you to understand the interconnected structure of disparate moments and even percieve the future.</p><p>It is a vortex into a singularity where &quot;all different kinds of truths fit together&quot; which kind of sounds like the git repo of an open source project to me. Plus this is a library software dev blog so it has to have a literary reference.</p><p>Vonnegut lived in <a href="https://www.sturgislibrary.org/pdf/beenbarnstable.pdf" target="_blank" rel="noreferrer">Barnstable Village</a> and served as a trustee of Sturgis Library, the <a href="https://www.sturgislibrary.org/history-of-the-library/" target="_blank" rel="noreferrer">oldest library building</a> in the United states.</p><h2 id="clips" tabindex="-1">Clips <a class="header-anchor" href="#clips" aria-label="Permalink to &quot;Clips&quot;">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=ubFUKxKtxRA" target="_blank" rel="noreferrer">Koha Community GiftED Webniar 2024: Koha Testing Docker</a></li><li><a href="https://vimeo.com/466377608/55460418a4#t=2h5m35s" target="_blank" rel="noreferrer">NEIUG 2020 Dahsboard Confessional</a></li></ul><h2 id="press" tabindex="-1">Press <a class="header-anchor" href="#press" aria-label="Permalink to &quot;Press&quot;">​</a></h2><ul><li><a href="https://bywatersolutions.com/news/july-2024-librarian-of-the-month-" target="_blank" rel="noreferrer">July 2024 Librarian of the Month</a></li><li><a href="https://bywatersolutions.com/news/bywater-solutions-partners-with-koha-us-to-raise-money-for-the-koha-community-2024" target="_blank" rel="noreferrer">Koha Community Challenge 2024 - Furthest distance 294 miles</a>🛹</li><li><a href="https://www.schoolofstjude.org/academics/students-taste-national-success/" target="_blank" rel="noreferrer">Students taste national success 2015</a></li><li><a href="https://scratched.gse.harvard.edu/stories/simple-strategies-interview-brendan-lawlor-boys-and-girls-club.html" target="_blank" rel="noreferrer">ScratchED interview 2012</a></li></ul><h2 id="todo" tabindex="-1">Todo <a class="header-anchor" href="#todo" aria-label="Permalink to &quot;Todo&quot;">​</a></h2><p>🥾 🐛 🥳</p><h2 id="how-s-this-site-made" tabindex="-1">How&#39;s this site made? <a class="header-anchor" href="#how-s-this-site-made" aria-label="Permalink to &quot;How&#39;s this site made?&quot;">​</a></h2><ul><li>Built with <a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a></li><li>Powered by <a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue</a></li><li>Authored in <a href="https://www.markdownguide.org/" target="_blank" rel="noreferrer">Markdown</a></li><li>Diagramed with <a href="https://mermaid.js.org/" target="_blank" rel="noreferrer">Mermaid</a></li><li>Hosted on <a href="https://pages.github.com/" target="_blank" rel="noreferrer">Github Pages</a></li></ul>',19)])])}const p=a(n,[["render",i]]);export{f as __pageData,p as default};
